SELECT COUNT(*) FROM loan_apply
WHERE status = 'COMPLETED'
  AND owner_org_id = #{orgId}
  AND deleted = 0
  AND updated_time BETWEEN #{start} AND #{end}

SELECT COALESCE(SUM(credit_amount), 0) FROM loan_apply
WHERE created_by = #{empId}
  AND deleted = 0
  AND created_time BETWEEN #{start} AND #{end}
